Add-Type @"
using System;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public class Win {
  public delegate bool EnumProc(IntPtr h, IntPtr l);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc cb, IntPtr l);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h, int c);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] public static extern bool BringWindowToTop(IntPtr h);
  [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr h, IntPtr a, int x, int y, int cx, int cy, uint f);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  public static List<string> List() {
    var res = new List<string>();
    EnumWindows((h, l) => {
      if (!IsWindowVisible(h)) return true;
      var sb = new StringBuilder(300);
      GetWindowTextW(h, sb, 300);
      if (sb.Length > 0) { uint pid; GetWindowThreadProcessId(h, out pid); res.Add(h.ToInt64() + "\t" + pid + "\t" + sb.ToString()); }
      return true;
    }, IntPtr.Zero);
    return res;
  }
  public static string Focus(long handle) {
    IntPtr h = new IntPtr(handle);
    ShowWindow(h, 9);
    SetWindowPos(h, new IntPtr(-1), 0,0,0,0, 0x0001 | 0x0002 | 0x0040);
    BringWindowToTop(h);
    SetForegroundWindow(h);
    System.Threading.Thread.Sleep(500);
    return GetForegroundWindow().ToInt64().ToString() + " vs " + handle;
  }
}
"@
