} elseif ($arg -eq 'paste') {
  Write-Output ("focus=" + [Win]::Focus([int64]$args[1]))
  Start-Sleep -Milliseconds 400
  [System.Windows.Forms.SendKeys]::SendWait('^v')
  Write-Output "pasted"
}
