if (-not $title) { $title = 'Hermes' }
Write-Output ([W2]::FindByTitle($title))
if ($args[1] -eq 'paste') {
  Start-Sleep -Milliseconds 350
  [System.Windows.Forms.SendKeys]::SendWait('^v')
